            require(sweep[str(experiment['FD_primary_h'])]['within_primary_budget'],'frozen primary FD force bound failed; do not choose best h');record['modes'].append({'mode':mode,'native':native,'C_sha256':sha(source),'header_sha256':sha(header),'binary_sha256':sha(binary),'output_sha256':sha(d/'forces.f64'),'SDK_force':sdk,'independent_force_sweep':sweep,'primary_h':experiment['FD_primary_h']});save()
